def sum_prefix_scores(words):
    root = {}

    for word in words:
        node = root
        for ch in word:
            node = node.setdefault(ch, {'count': 0})
            node['count'] += 1

    answer = []
    for word in words:
        node = root
        total = 0
        for ch in word:
            node = node[ch]
            total += node['count']
        answer.append(total)

    return answer

